CREATE FUNCTION ogr_system_tables.event_trigger_function_for_metadata() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    obj record;
BEGIN
  IF has_schema_privilege('ogr_system_tables', 'USAGE') THEN
   IF has_table_privilege('ogr_system_tables.metadata', 'DELETE') THEN
    FOR obj IN SELECT * FROM pg_event_trigger_dropped_objects()
    LOOP
        IF obj.object_type = 'table' THEN
            DELETE FROM ogr_system_tables.metadata m WHERE m.schema_name = obj.schema_name AND m.table_name = obj.object_name;
        END IF;
    END LOOP;
   END IF;
  END IF;
END;
$$;


--
-- Name: calcular_attr(bigint[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calcular_attr(enlaces_fallados bigint[] DEFAULT '{}'::bigint[]) RETURNS TABLE(cantidad_nodos bigint, pares_posibles bigint, pares_conectados bigint, attr numeric)
    LANGUAGE sql STABLE
    AS $$
WITH componentes AS MATERIALIZED (
    SELECT node, component
    FROM pgr_connectedComponents(FORMAT(
        'SELECT id, source, target, cost, cost AS reverse_cost
         FROM public.enlaces
         WHERE NOT (id = ANY(%L::BIGINT[]))',
        ARRAY_REMOVE(COALESCE(enlaces_fallados, '{}'::BIGINT[]), NULL::BIGINT)
    ))
), grupos AS (
    SELECT COALESCE(c.component, -n.id) AS componente,
           COUNT(*)::NUMERIC AS cantidad
    FROM public.nodos_clave AS n
    LEFT JOIN componentes AS c ON c.node = n.id
    GROUP BY COALESCE(c.component, -n.id)
), totales AS (
    SELECT COALESCE(SUM(cantidad), 0) AS nodos,
           COALESCE(SUM(cantidad * (cantidad - 1) / 2), 0) AS pares
    FROM grupos
)
SELECT nodos::BIGINT, (nodos * (nodos - 1) / 2)::BIGINT, pares::BIGINT,
       CASE WHEN nodos > 1 THEN pares / (nodos * (nodos - 1) / 2) END
FROM totales;
$$;


