--
-- Name: nodos_clave; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.nodos_clave AS
 WITH grupos AS (
         SELECT catalogo_nodos.vertice_id AS id,
            (array_agg(catalogo_nodos.geom_acceso ORDER BY catalogo_nodos.clave))[1] AS geom,
            array_agg(catalogo_nodos.nombre ORDER BY catalogo_nodos.clave) AS instalaciones,
            array_agg(catalogo_nodos.localidad ORDER BY catalogo_nodos.clave) AS ciudades,
            array_agg(catalogo_nodos.clave ORDER BY catalogo_nodos.clave) AS claves_catalogo
           FROM public.catalogo_nodos
          WHERE (catalogo_nodos.evaluar AND (catalogo_nodos.vertice_id IS NOT NULL))
          GROUP BY catalogo_nodos.vertice_id
        )
 SELECT id,
    geom,
    ARRAY( SELECT (SUBSTRING(n.clave FROM 9))::bigint AS "substring"
           FROM public.catalogo_nodos n
          WHERE (n.evaluar AND (n.vertice_id = g.id) AND (n.origen = 'peeringdb'::text))
          ORDER BY n.clave) AS instalaciones_ids,
    instalaciones,
    ciudades,
    ARRAY( SELECT DISTINCT r.rol
           FROM (public.catalogo_nodos n
             CROSS JOIN LATERAL unnest(n.roles) r(rol))
          WHERE (n.evaluar AND (n.vertice_id = g.id))
          ORDER BY r.rol) AS roles,
    claves_catalogo,
    ARRAY( SELECT DISTINCT c.categoria
           FROM (public.catalogo_nodos n
             CROSS JOIN LATERAL unnest(n.categorias) c(categoria))
          WHERE (n.evaluar AND (n.vertice_id = g.id))
          ORDER BY c.categoria) AS categorias,
    ARRAY( SELECT DISTINCT f.fuente
           FROM (public.catalogo_nodos n
             CROSS JOIN LATERAL unnest(n.fuentes) f(fuente))
          WHERE (n.evaluar AND (n.vertice_id = g.id))
          ORDER BY f.fuente) AS fuentes
   FROM grupos g;


--
-- Name: VIEW nodos_clave; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.nodos_clave IS 'Accesos distintos seleccionados del catalogo. Las ubicaciones de referencia y asociaciones aproximadas se conservan en catalogo_nodos. El conjunto y el denominador son fijos durante cada comparacion.';


--
-- Name: nodos_clave_candidatos; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.nodos_clave_candidatos AS
 WITH grupos AS (
         SELECT catalogo_nodos.vertice_id AS id,
            (array_agg(catalogo_nodos.geom_acceso ORDER BY catalogo_nodos.clave))[1] AS geom,
            array_agg(catalogo_nodos.clave ORDER BY catalogo_nodos.clave) AS claves_catalogo,
            array_agg(catalogo_nodos.nombre ORDER BY catalogo_nodos.clave) AS nombres,
            count(*) AS registros_asociados
           FROM public.catalogo_nodos
          WHERE (catalogo_nodos.evaluar AND (catalogo_nodos.vertice_id IS NOT NULL))
          GROUP BY catalogo_nodos.vertice_id
        )
 SELECT id,
    geom,
    claves_catalogo,
    nombres,
    registros_asociados,
    ARRAY( SELECT DISTINCT r.rol
           FROM (public.catalogo_nodos n
             CROSS JOIN LATERAL unnest(n.roles) r(rol))
          WHERE (n.evaluar AND (n.vertice_id = g.id))
          ORDER BY r.rol) AS roles,
    ARRAY( SELECT DISTINCT c.categoria
           FROM (public.catalogo_nodos n
             CROSS JOIN LATERAL unnest(n.categorias) c(categoria))
          WHERE (n.evaluar AND (n.vertice_id = g.id))
          ORDER BY c.categoria) AS categorias
   FROM grupos g;


