--
-- Name: referencias_proximidad; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.referencias_proximidad AS
 SELECT instalacion.id,
    instalacion.nombre,
    instalacion.ciudad,
    instalacion.geom,
    ARRAY( SELECT intercambio.nombre
           FROM (public.referencias_presencias presencia
             JOIN public.referencias_intercambios intercambio ON ((intercambio.id = presencia.intercambio_id)))
          WHERE (presencia.instalacion_id = instalacion.id)
          ORDER BY intercambio.nombre, intercambio.id) AS intercambios,
    cercano.id AS enlace_cercano,
    cercano.distancia_m
   FROM (public.referencias_instalaciones instalacion
     LEFT JOIN LATERAL ( SELECT enlace.id,
            public.st_distance((instalacion.geom)::public.geography, (enlace.geom)::public.geography) AS distancia_m
           FROM public.enlaces enlace
          WHERE (instalacion.geom IS NOT NULL)
          ORDER BY (public.st_distance((instalacion.geom)::public.geography, (enlace.geom)::public.geography)), enlace.id
         LIMIT 1) cercano ON (true));


